layers.vertex:
attribute vec4 aA, aK, aT; attribute vec3 aC; uniform float uTime;
    varying vec2 vQ; varying float vK, vLum, vTaper, vSeed, vFace; varying vec3 vCol;
    vec3 W(vec3 l){ float c = cos(aA.w), s = sin(aA.w); return aA.xyz + vec3(c*l.x + s*l.z, l.y, -s*l.x + c*l.z); }
    vec3 WD(vec3 l){ float c = cos(aA.w), s = sin(aA.w); return vec3(c*l.x + s*l.z, l.y, -s*l.x + c*l.z); }
    float eo3(float x){ x = clamp(x, 0., 1.); return 1. - pow(1. - x, 3.); }
    void main(){
      float kind = aK.x, age = uTime - aT.x, te = uTime - aT.y, rt = uTime - aT.z, why = aT.w;
      float rdur = why > 2.5 ? .12 : .2;
      if (age < 0. || te > .3 || rt > rdur){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float endk = clamp(te/.3, 0., 1.), rp = rt < 0. ? 0. : rt/rdur, cl = (why > 1.5 && why < 2.5) ? eo3(rp) : 0.;
      float grow = eo3(age/.15), fade = (1. - endk)*(1. - rp)*(age < .033 ? 1.6 : 1.);
      float s = position.x + .5, y = position.y*2.;
      vQ = vec2(s, y); vK = kind; vCol = aC; vSeed = 0.; vFace = 1.; vTaper = 1.;
      vec3 Pw, Tw; float Wd = .02, lum = fade, taper = 1.;

      if (kind < 1.5){
        // STUN: small 4-point star on a horizontal orbit around the head, outside the Sleep bubble
        float a = uTime*2.2 + aK.y*1.0472, R = .33*mix(.3, 1., grow)*(1. + .7*cl)*(1. - .5*endk);
        vec3 P = vec3(cos(a)*R, 1.8 + .025*sin(a*2. + aK.y), sin(a)*R);
        vec4 mv = viewMatrix*vec4(W(P), 1.);
        mv.xy += position.xy*2.*.07*(1. - .4*endk);
        vQ = position.xy*2.; vSeed = uTime*3. + aK.y; vLum = fade*(.9 + .2*sin(uTime*6. + aK.y*2.));
        gl_Position = projectionMatrix*mv; return;
      }
      if (kind < 2.5){
        // SLEEP: small translucent bubble sitting on top of the head like a hat (impostor pushed to its front surface), slow swirling core
        vec4 mv = viewMatrix*vec4(W(vec3(0., 2.03, 0.)), 1.);
        float R = .15*mix(.4, 1., grow)*(1. + .03*sin(uTime*1.6))*(1. + .35*endk)*(1. + .5*cl);
        mv.xyz += normalize(-mv.xyz)*R*.9; mv.xy += position.xy*2.*R;
        vQ = position.xy*2.; vLum = fade*(1. - endk);
        gl_Position = projectionMatrix*mv; return;
      }
      if (kind > 3.5 && kind < 4.5){
        // TAUNT: anger mark at the temple on the taunter's side, throbbing like a pulse of rage
        vec3 H = W(vec3(0., 1.76, 0.)), ds = aK.yzw - H; ds.y = 0.; ds = normalize(ds + vec3(1e-4, 0., 0.));
        vec4 mv = viewMatrix*vec4(H + ds*.2 + vec3(0., .1, 0.), 1.); mv.xyz += normalize(-mv.xyz)*.12;
        float th = pow(.5 + .5*sin(uTime*9.), 6.);
        mv.xy += position.xy*2.*.09*mix(.3, 1., grow)*(1. + .15*th)*(1. + .8*cl)*(1. - .4*endk);
        vQ = position.xy*2.; vLum = fade*(.85 + .35*th);
        gl_Position = projectionMatrix*mv; return;
      }
      if (kind > 6.5 && kind < 7.5){
        // FEAR: a smoke face with red eyes hovers above the head (over the Sleep bubble), always visible, bobbing; the mouth keeps screaming
        float ph = fract(uTime/2.2 + aK.y*.37);
        vec4 mv = viewMatrix*vec4(W(vec3(0., 2.42, 0.)), 1.);
        mv.x += .02*sin(uTime*1.7); mv.y += .03*sin(uTime*1.3 + 1.);
        mv.xy += position.xy*2.*.24*(1. - .4*endk)*(1. + .6*cl);
        vQ = position.xy*2.; vSeed = ph; vLum = fade*grow;
        gl_Position = projectionMatrix*mv; return;
      }
      if (kind > 9.5 && kind < 10.5){
        // FD wake: quad spanning backwards from the torso along -move, vertical width; fades when seen end-on
        vec3 d = normalize(vec3(aK.y, 0., aK.z)), up = vec3(0., 1., 0.);
        vec3 P = aA.xyz + vec3(0., 1.0, 0.) - d*(.15 + s*1.1) + up*position.y*1.3;
        vFace = abs(dot(cross(d, up), normalize(cameraPosition - P)));
        vQ = vec2(s, y); vLum = fade*smoothstep(0., .1, age);
        gl_Position = projectionMatrix*viewMatrix*vec4(P, 1.); return;
      }
      if (kind < 3.5){
        // SILENCE: thin closed stitched ring lying on top of the head (the brim of the Sleep hat when both are on)
        float R = .19*mix(1.8, 1., grow)*(1. + .8*cl), a = s*6.28318;
        Pw = W(vec3(cos(a)*R, 1.92, sin(a)*R)); Tw = WD(vec3(-sin(a), 0., cos(a))); Wd = .032;
      } else if (kind < 6.5){
        // TAUNT tether: brief line source → target on apply only (the mark itself is the anger symbol above)
        vec3 H = W(vec3(0., 1.76, 0.)), src = aK.yzw, ds = src - H; ds.y = 0.; ds = normalize(ds + vec3(1e-4, 0., 0.));
        vec3 up = vec3(0., 1., 0.), nr = normalize(up*cos(.4) + ds*sin(.4)), e1 = normalize(ds - nr*dot(ds, nr)), e2 = cross(nr, e1);
        float R = .4*mix(.6, 1., grow)*(1. + .6*cl);
        {
          if (age > .36){ gl_Position = vec4(2.,2.,2.,1.); return; }
          vec3 S0 = vec3(src.x, 1.2, src.z);
          float hd = eo3(age/.12), tl = clamp((age - .12)/.22, 0., 1.), sp = mix(tl, hd, s);
          Pw = mix(S0, H, sp) + up*.18*sin(3.14159*sp); Tw = H - S0 + up*.5*cos(3.14159*sp);
          taper = pow(sin(3.14159*s), .5); Wd = .018; lum *= 1. - smoothstep(.22, .36, age);
        }
      } else {
        // FD: two chevrons lying ahead of the waist, pointing along the movement, pulsing forward
        vec3 d = normalize(vec3(aK.z, 0., aK.w)), pp = vec3(-d.z, 0., d.x);
        vec3 c = aA.xyz + vec3(0., 1.0, 0.) + d*(.42 + .15*aK.y);
        vec3 tip = c + d*.06, aL = c - d*.07 + pp*.11, aR = c - d*.07 - pp*.11;
        Pw = s < .5 ? mix(aL, tip, s*2.) : mix(tip, aR, (s - .5)*2.); Tw = s < .5 ? tip - aL : aR - tip;
        taper = smoothstep(0., .15, s)*smoothstep(1., .85, s); Wd = .024; lum *= .55 + .45*sin(uTime*18. - aK.y*1.6);
      }
      vec3 side = normalize(cross(Tw, Pw - cameraPosition));
      vLum = lum; vTaper = taper;
      gl_Position = projectionMatrix*viewMatrix*vec4(Pw + side*y*Wd, 1.);
    }

layers.fragment:
uniform float uTime; varying vec2 vQ; varying float vK, vLum, vTaper, vSeed, vFace; varying vec3 vCol;
    void main(){
      vec3 o; vec3 wh = mix(vCol, vec3(1.), .6);
      if (vK > 3.5 && vK < 4.5){
        // anger mark: four arcs bowing towards the centre around a cross-shaped gap
        vec2 q = vQ, a = abs(q); float d = abs(length(a - vec2(.62, .62)) - .46);
        float m = step(.1, a.x)*step(.1, a.y)*smoothstep(.8, .6, length(q));
        float st = exp(-d*d/.0045)*m, cr = exp(-d*d/.0012)*m;
        o = (vCol*st*1.8 + mix(vCol, vec3(1.), .25)*cr*.7)*vLum*smoothstep(1., .85, length(q));
      } else if (vK > 6.5 && vK < 7.5){
        // ghost face: dim red smoke oval with a torn tail, hot red eyes, mouth opening into a scream
        vec2 q = vQ; float ph = vSeed, al = 1.;                                             // always visible
        float nz = fract(sin(dot(floor(q*6. + vec2(0., uTime*2.)), vec2(12.9, 78.2)))*43758.5);
        float n2 = .5 + .5*sin(q.x*9. + uTime*3.)*sin(q.y*7. - uTime*2.4);
        float body = smoothstep(.72, .4, length(q*vec2(1.25, q.y < -.1 ? .62 : 1.) - vec2(0., .05)) + (n2 - .5)*.35 + (nz - .5)*.08);
        vec2 e = vec2(abs(q.x) - .21, q.y - .14 + (abs(q.x) - .21)*.45);
        float eye = exp(-(e.x*e.x/.005 + e.y*e.y/.0012));
        float mo = length((q - vec2(0., -.2))/vec2(.09, .15*(.45 + .55*sin(3.14159*ph))));   // scream opens and closes
        float mouth = smoothstep(1.1, .8, mo);
        float lum = body*.16*(1. - mouth) + exp(-pow((mo - 1.)/.2, 2.))*body*.22;
        o = (vCol*(lum*.8 + eye*1.8) + vec3(1., .72, .5)*eye*.9)*al*vLum*smoothstep(1., .85, length(q));
      } else if (vK < 1.5){
        float c = cos(vSeed), s = sin(vSeed); vec2 q = vec2(c*vQ.x - s*vQ.y, s*vQ.x + c*vQ.y); float r = length(q);
        float rays = exp(-abs(q.x*q.y)*70.)*smoothstep(.95, .1, r), core = exp(-r*r*30.), hal = exp(-r*r*12.)*.1;
        o = (vCol*(rays + core + hal) + wh*(core + rays*.3)*.6)*vLum*smoothstep(1., .85, r);
      } else if (vK < 2.5){
        vec2 q = vQ; float r = length(q); if (r > 1.) discard;
        float rim = pow(smoothstep(.45, 1., r), 2.2)*smoothstep(1., .93, r), body = .05;
        float hl = exp(-dot(q - vec2(-.38, .42), q - vec2(-.38, .42))*30.)*.45;
        float ang = atan(q.y, q.x), arms = pow(.5 + .5*cos(3.*ang + r*9. - uTime*2.5), 5.)*exp(-r*r*6.)*.7, core = exp(-r*r*30.)*1.1;
        o = (vCol*(rim*.06 + body*.3 + arms*.45 + core*.35) + wh*(rim*.02 + core*.55 + hl*.35)*.5)*vLum;   // border barely there: the swirling core is the read
      } else if (vK > 9.5 && vK < 10.5){
        vec2 q = vQ; float a = 0.;
        for (int i=0;i<4;i++){ float fi = float(i), y0 = -.55 + fi*.36 + .06*sin(fi*3.1), L = .55 + .35*fract(fi*.618);
          a += exp(-pow((q.y - y0)/.022, 2.))*smoothstep(1., .2, q.x/L)*smoothstep(0., .08, q.x)*(.55 + .45*sin(q.x*14. - uTime*22. + fi*2.)); }
        o = vCol*a*.55*vLum*smoothstep(.15, .5, vFace);
      } else {
        float y = vQ.y, core = exp(-y*y/.03), halo = exp(-y*y/.2), f = vTaper*vLum;
        o = vCol*halo*.6*f + wh*core*.85*f;
        if (vK > 2.5 && vK < 3.5){                                   // Silence: cross stitches over the closed line
          float st = (1. - smoothstep(.015, .035, abs(fract(vQ.x*10.) - .5)))*exp(-y*y/.5);
          o = vCol*halo*.35*f + wh*core*.55*f + (vCol + wh*.6)*st*f;
        }
      }
      if (max(o.r, max(o.g, o.b)) < .002) discard;
      gl_FragColor = vec4(o, 1.);
    }

layers.vertex:
varying vec3 vPortNormal,vPortPosition;


  attribute vec4 aA, aP, aK, aT; uniform float uTime; varying float vS, vHead, vBark, vLeaf;
  vec3 Wr(vec3 l){ float c = cos(aA.w), s = sin(aA.w); return aA.xyz + vec3(c*l.x + s*l.z, l.y, -s*l.x + c*l.z); }
  vec3 WDr(vec3 l){ float c = cos(aA.w), s = sin(aA.w); return vec3(c*l.x + s*l.z, l.y, -s*l.x + c*l.z); }
  float snapE, openR;
  vec3 coil(float s){                                            // one coil around both legs together, wide → tight on the snap
    float a = aP.x + s*aP.y*6.2832 + (1. - snapE)*1.2, R = (.23 - .05*s)*(1. + 1.4*(1. - snapE))*openR;
    vec3 wob = vec3(.008*sin(s*23. + aP.w*9.), 0., .008*cos(s*19. + aP.w*5.));
    return vec3(.12*aK.x, 0., -.02) + vec3(cos(a)*R, s*aP.z, sin(a)*R) + wob;
  }
  vec3 gP, gN; float gAlive;
void main(){

  float u = uTime - aT.x, te = uTime - aT.y, rt = uTime - aT.z;
  float rdur = aT.w > 2.5 ? .12 : .2;
  gAlive = (u >= 0. && te < .3 && rt < rdur) ? 1. : 0.;
  snapE = 1. - pow(1. - clamp(u/.12, 0., 1.), 3.);
  float brk = (rt > 0. && aT.w > 1.5 && aT.w < 2.5) ? clamp(rt/rdur, 0., 1.) : 0.;
  openR = 1. + 1.5*brk;                                          // Cleanse: the coil bursts open
  float gone = max(clamp(te/.3, 0., 1.), rt > 0. ? clamp(rt/rdur, 0., 1.) : 0.);
  vHead = min(snapE*1.05, 1. - gone);                            // grows up in the snap; dissolves top-down when it ends
  vLeaf = 0.;
  if (aK.y < 0.){                                                // vine tube
    float s = position.y + .5; vec3 C = coil(s), T = normalize(coil(min(s + .01, 1.)) - coil(max(s - .01, 0.)));
    vec3 B = normalize(cross(T, vec3(0., 1., 0.))), Nn = cross(B, T);
    float ang = atan(position.z, position.x), rad = mix(.028, .01, s)*(1. + .12*sin(s*31. + aP.w*5.));
    vec3 rn = B*cos(ang) + Nn*sin(ang);
    gP = Wr(C + rn*rad); gN = WDr(rn); vS = s; vBark = ang;
  } else {                                                       // leaf opening on the vine
    float s = aK.y; vec3 C = coil(s), T = normalize(coil(min(s + .01, 1.)) - coil(max(s - .01, 0.)));
    vec3 ow = normalize(C - vec3(.12*aK.x, C.y, -.02)), lx = normalize(ow + T*.6 + vec3(0., .3, 0.)), ly = normalize(cross(lx, T));
    float sc = .09*smoothstep(.5, 1., snapE)*(1. - gone), fl = sin(uTime*1.3 + aP.w*20.)*.08*position.x;
    gP = Wr(C + ow*.015 + (lx*position.x + ly*position.y + cross(lx, ly)*fl)*sc); gN = WDr(normalize(cross(lx, ly))); vS = aK.y; vBark = -10.; vLeaf = 1.;
  }
  vec3 objectNormal = gN;
vec3 transformed = gAlive > .5 ? gP : vec3(0., -60., 0.);
vPortNormal=objectNormal;vPortPosition=transformed;gl_Position=projectionMatrix*modelViewMatrix*vec4(transformed,1.);}

layers.fragment:
varying vec3 vPortNormal,vPortPosition;

varying float vS, vHead, vBark, vLeaf;
void main(){vec4 diffuseColor=vec4(1.);vec3 totalEmissiveRadiance=vec3(0.);vec3 normal=normalize(vPortNormal);vec3 vViewPosition=cameraPosition-vPortPosition;

  if (vLeaf < .5 && vS > vHead) discard;

        if (vLeaf > .5) diffuseColor.rgb = vec3(.15, .21, .07);                                     // leaf: dark green
        else { float ridge = smoothstep(.2, .8, .5 + .5*sin(vBark*5. + sin(vS*28.)*1.3));
          vec3 bark = mix(vec3(.09, .065, .04), vec3(.24, .18, .11), ridge);
          bark = mix(bark, vec3(.12, .15, .06), smoothstep(.55, .95, sin(vS*9. + vBark*1.7)*.5 + .5)*.5);   // moss patches
          diffuseColor.rgb = mix(bark, vec3(.16, .2, .06), .45); }

        if (vLeaf < .5){ float rim = pow(1. - abs(dot(normal, normalize(vViewPosition))), 3.);
          totalEmissiveRadiance += vec3(.5, .82, .29)*(.04 + rim*.5); }                            // faint Root-green rim, not a beam
gl_FragColor=vec4(diffuseColor.rgb,1.);}

layers.vertex:
attribute vec3 aO;attribute float aT;attribute vec2 aP;uniform float uTime;varying float vS,vY,vU;
void main(){float u=uTime-aT;if(u<0.||u>3.0){gl_Position=vec4(2.,2.,2.,1.);return;}float s=uv.x,y=uv.y*2.-1.,rise=smoothstep(0.,.18,u);
float angle=aP.x+s*4.8;float R=.15+.10*sin(3.14159*s),H=.035+s*.50;
vec3 P=aO+vec3(cos(angle)*R,H,sin(angle)*R)*rise;vec3 outdir=vec3(cos(angle),0.,sin(angle));
P+=outdir*y*(.012+.025*sin(3.14159*s));vS=s;vY=y;vU=u;gl_Position=projectionMatrix*viewMatrix*vec4(P,1.);}

layers.fragment:
uniform vec3 uSkill;varying float vS,vY,vU;
void main(){float prof=pow(max(sin(3.14159*vS),0.),.55),core=exp(-vY*vY*19.),halo=exp(-vY*vY*4.);
float f=smoothstep(0.,.07,vU)*(1.-smoothstep(2.8,3.0,vU)),energy=.65+.35*sin(vS*11.-vU*1.2);
vec3 c=uSkill*(core*.46+halo*.13)*prof*f*energy;gl_FragColor=vec4(c,1.);}
